def main():
    print(f"NEET PG Topics Count: {len(NEET_PG_TOPICS)}")
    print(f"MRCP Topics Count: {len(MRCP_TOPICS)}")
    
    assert len(NEET_PG_TOPICS) == 100, f"Expected 100 NEET PG topics, got {len(NEET_PG_TOPICS)}"
    assert len(MRCP_TOPICS) == 100, f"Expected 100 MRCP topics, got {len(MRCP_TOPICS)}"
    
    for i, t in enumerate(NEET_PG_TOPICS):
        assert t[1] in TAXONOMY_SUBJECTS, f"Invalid subject {t[1]} at NEET PG #{i}: {t[0]}"
        assert t[2] in TAXONOMY_SYSTEMS, f"Invalid system {t[2]} at NEET PG #{i}: {t[0]}"
        assert t[5].startswith("https://"), f"Invalid URL at NEET PG #{i}: {t[5]}"
        
    for i, t in enumerate(MRCP_TOPICS):
        assert t[1] in TAXONOMY_SUBJECTS, f"Invalid subject {t[1]} at MRCP #{i}: {t[0]}"
        assert t[2] in TAXONOMY_SYSTEMS, f"Invalid system {t[2]} at MRCP #{i}: {t[0]}"
        assert t[5].startswith("https://"), f"Invalid URL at MRCP #{i}: {t[5]}"
        
    out_path = os.path.join(os.path.dirname(__file__), "mega93_topics_a.py")
    with open(out_path, "w", encoding="utf-8") as f:
        f.write("# Auto-generated Mega-Batch 93 Part A topics (NEET PG 100, MRCP 100)\n\n")
        f.write(f"NEET_PG_TOPICS = {json.dumps(NEET_PG_TOPICS, indent=2)}\n\n")
        f.write(f"MRCP_TOPICS = {json.dumps(MRCP_TOPICS, indent=2)}\n")
        
    print(f"Saved Part A topics to {out_path}!")

if __name__ == "__main__":
    main()
